def revise(n,c):
    theory,application=additions(n)
    def insert(key,title,blocks,phase,at):
        if not blocks:return
        c['sections'].insert(at,dict(id=key,title=title,body=''.join(b for _,b in blocks),phase=phase))
        c['headlines'][key]=[t for t,_ in blocks]
    # Core prerequisites precede the established theory that uses them.
    first_theory=next(i for i,s in enumerate(c['sections']) if s['phase']=='General theory')
    if n in [3,4]:
        foundation_index=next((i for i,s in enumerate(c['sections']) if s['id']=='theory-foundations'),None)
        if foundation_index is not None:first_theory=foundation_index+1
    if n in [7,8,10]:
        first_theory=next(i for i,s in enumerate(c['sections']) if s['phase']=='Worked application')
    if n==9:first_theory=next(i for i,s in enumerate(c['sections']) if s['id']=='matching-theory')
    if n==5:
        # Move the multiple-model definition before its inference section.
        foundation=next((s for s in c['sections'] if s['id']=='theory-foundations'),None)
        if foundation:
            c['sections'].remove(foundation);c['sections'].insert(first_theory,foundation)
        specification=next(s for s in c['sections'] if s['id']=='theory-specification')
        c['sections'].remove(specification);c['sections'].insert(first_theory+1,specification)
        first_theory+=1
    insert('reasoning-foundations','Connect the foundations before calculating',theory,'General theory',first_theory)
    # Enrich the application before its final operating decision.
    at=next(i for i,s in enumerate(c['sections']) if s['id']=='act')
    insert('reasoning-worked','Work through the reasoning gap',application,'Worked application',at)
    if n==5:
        order=['read-data','calculate','reasoning-worked','controls','interpret','regression-uncertainty',
               'interval-bands','model-comparison','residual-review','act']
        by_id={s['id']:s for s in c['sections'] if s['phase']=='Worked application'}
        assert set(order)==set(by_id)
        c['sections']=[s for s in c['sections'] if s['phase']=='General theory']+[by_id[key] for key in order]
    prompt,flaw,transfer,criteria=TASKS[n]
    practice=[
        item('Reconstruct the calculation before inspecting the worked answer',bullets(prompt,flaw),
             'Work independently or explain your reasoning to a partner. State the target, units and assumptions before calculating. The student notebook provides runnable setup and separate task cells; the companion solution checks the calculation. The lesson’s completed lab remains available as a reference, with its steps separated into smaller cells.'),
        item('Transfer the method and defend the decision',bullets(transfer,'Submit a calculation, an assumption and a justified next action'),
             'An acceptable answer can recommend more information, a narrower claim or no action. It must connect the method to the target and explain the consequence of a failed assumption. Use the assessment criteria after attempting the task; matching a supplied recommendation is not the grading objective.')]
    insert('independent-practice','Explain, reconstruct, diagnose and transfer',practice,'Decision and synthesis',len(c['sections']))
    # Reading-only answer disclosure is kept outside presentation source frames.
    c['practice_criteria']=criteria
    return c
